export function combine(rows: MediaRow[]): MediaRow { return rows.reduce((total, row) => ({ imp: total.imp + row.imp, clicks: total.clicks + row.clicks, cost: total.cost + row.cost, cv: total.cv + row.cv }), { imp: 0, clicks: 0, cost: 0, cv: 0 }); }
export function getRow(day: DailyRow, media: MediaKey): MediaRow { return media === "all" ? day.total : day[media]; }
export function yen(value: number) { return `¥${Math.round(value).toLocaleString("ja-JP")}`; }
export function num(value: number) { return Math.round(value).toLocaleString("ja-JP"); }
export function pct(value: number, digits = 1) { return `${value.toFixed(digits)}%`; }
